WITH scored AS (SELECT id, order_id, method, amount, paid_at, status, AVG(amount) OVER (PARTITION BY order_id) AS order_id_avg_amount, ROW_NUMBER() OVER (PARTITION BY method, order_id ORDER BY paid_at DESC, id) AS event_seq, DENSE_RANK() OVER w_recent AS amount_dense_rank, LAG(amount, 1) OVER w_ordered AS prev_amount, LAG(amount, 1) OVER (PARTITION BY status, method ORDER BY amount, id) AS prev_amount_2 FROM payments WINDOW w_recent AS (PARTITION BY status ORDER BY amount DESC), w_ordered AS (PARTITION BY order_id ORDER BY amount, id)) SELECT CASE WHEN prev_amount >= 1650 THEN 'HIGH' ELSE 'LOW' END AS prev_amount_tier, SORT_ARRAY(COLLECT_SET(method)) AS method_list, (UNIX_TIMESTAMP(MAX(paid_at)) - UNIX_TIMESTAMP(MIN(paid_at))) / 60 AS duration_min, PERCENTILE_APPROX(prev_amount, ARRAY(0.25, 0.5, 0.75)) AS prev_amount_quartiles, COUNT(*) FILTER (WHERE method = 'paypal') AS paypal_rows FROM scored GROUP BY CUBE (CASE WHEN prev_amount >= 1650 THEN 'HIGH' ELSE 'LOW' END);
